const ELEMENT_PROP_KEYS = new Set(["theme","accent","quoteDuration","stagger","sweep","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  quoteDuration: 120,
  stagger: 5,
  sweep: 18,
  fontFamily: "Instrument Serif",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type QuoteHeroElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof QuoteHeroBase>;

const QuoteHeroInner = forwardRef<
  HTMLDivElement,
  QuoteHeroElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<QuoteHero>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <QuoteHeroBase
          {...(componentProps as unknown as ComponentProps<typeof QuoteHeroBase>)}
        />
      </div>
    </Sequence>
  );
});

export const QuoteHero = Interactive.withSchema({
  Component: QuoteHeroInner,
  componentName: "<QuoteHero>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
